-- =============================================================================
-- Kimi — Water
-- water_logs (personal, offline-first), water_plans + water_plan_days
-- (weekly plan a professor writes for a competitor of the academy).
-- =============================================================================

create table public.water_logs (
  -- Generated by the app so an offline log can be re-sent (upsert) safely.
  id uuid primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  amount_ml integer not null check (amount_ml between 1 and 5000),
  logged_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index water_logs_user_logged_at_idx on public.water_logs (user_id, logged_at desc);

create table public.water_plans (
  id uuid primary key default gen_random_uuid(),
  athlete_id uuid not null references public.profiles (id) on delete cascade,
  academy_id uuid not null references public.academies (id) on delete cascade,
  -- Monday of the week.
  week_start date not null check (extract(isodow from week_start) = 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (athlete_id, academy_id, week_start)
);
create index water_plans_academy_id_idx on public.water_plans (academy_id);

create table public.water_plan_days (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.water_plans (id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6),
  target_ml integer not null check (target_ml between 1 and 20000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (plan_id, weekday)
);

create trigger water_logs_set_updated_at before update on public.water_logs
  for each row execute function private.set_updated_at();
create trigger water_plans_set_updated_at before update on public.water_plans
  for each row execute function private.set_updated_at();
create trigger water_plan_days_set_updated_at before update on public.water_plan_days
  for each row execute function private.set_updated_at();

-- -----------------------------------------------------------------------------
-- Access
-- -----------------------------------------------------------------------------
alter table public.water_logs enable row level security;
alter table public.water_plans enable row level security;
alter table public.water_plan_days enable row level security;

grant select, insert, update, delete on public.water_logs to authenticated;
grant select, insert, update, delete on public.water_plans, public.water_plan_days to authenticated;

-- water_logs
create policy "water_logs: read own or as professor of the competitor"
  on public.water_logs for select to authenticated
  using (user_id = (select auth.uid()) or private.is_professor_of_competitor(user_id));
create policy "water_logs: insert own"
  on public.water_logs for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy "water_logs: update own"
  on public.water_logs for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
create policy "water_logs: delete own"
  on public.water_logs for delete to authenticated
  using (user_id = (select auth.uid()));

-- water_plans: the competitor reads their own; the professor manages plans of
-- competitors of their academy (is_competitor_of also checks the caller).
create policy "water_plans: competitor reads own, professor reads competitors"
  on public.water_plans for select to authenticated
  using (
    (athlete_id = (select auth.uid()) or private.is_professor(academy_id))
    and private.is_competitor_of(athlete_id, academy_id)
  );
create policy "water_plans: professor inserts"
  on public.water_plans for insert to authenticated
  with check (private.is_professor(academy_id) and private.is_competitor_of(athlete_id, academy_id));
create policy "water_plans: professor updates"
  on public.water_plans for update to authenticated
  using (private.is_professor(academy_id) and private.is_competitor_of(athlete_id, academy_id))
  with check (private.is_professor(academy_id) and private.is_competitor_of(athlete_id, academy_id));
create policy "water_plans: professor deletes"
  on public.water_plans for delete to authenticated
  using (private.is_professor(academy_id) and private.is_competitor_of(athlete_id, academy_id));

-- water_plan_days follow their plan.
create policy "water_plan_days: read with plan"
  on public.water_plan_days for select to authenticated
  using (exists (
    select 1 from public.water_plans p
    where p.id = plan_id
      and (p.athlete_id = (select auth.uid()) or private.is_professor(p.academy_id))
      and private.is_competitor_of(p.athlete_id, p.academy_id)
  ));
create policy "water_plan_days: professor inserts"
  on public.water_plan_days for insert to authenticated
  with check (exists (
    select 1 from public.water_plans p
    where p.id = plan_id
      and private.is_professor(p.academy_id)
      and private.is_competitor_of(p.athlete_id, p.academy_id)
  ));
create policy "water_plan_days: professor updates"
  on public.water_plan_days for update to authenticated
  using (exists (
    select 1 from public.water_plans p
    where p.id = plan_id
      and private.is_professor(p.academy_id)
      and private.is_competitor_of(p.athlete_id, p.academy_id)
  ))
  with check (exists (
    select 1 from public.water_plans p
    where p.id = plan_id
      and private.is_professor(p.academy_id)
      and private.is_competitor_of(p.athlete_id, p.academy_id)
  ));
create policy "water_plan_days: professor deletes"
  on public.water_plan_days for delete to authenticated
  using (exists (
    select 1 from public.water_plans p
    where p.id = plan_id
      and private.is_professor(p.academy_id)
      and private.is_competitor_of(p.athlete_id, p.academy_id)
  ));
